SourceCode.Declaration:
/// <summary>
/// How far apart two counters may be and still match, by counting group and item group. Most
/// specific row wins: both, then counting group, then item group, then the blank row. No row at
/// all means the two counts must be equal, which is also what zeros on a row mean.
/// </summary>
public class HSMobileOpsCountDualTolerance extends common
{
}

Method.Source:
/// <summary>[quantity, percent] for this counting group and item group.</summary>
public static container toleranceLimits(CountGroupId _countGroup, ItemGroupId _itemGroup)
{
    HSMobileOpsCountDualTolerance row;

    select firstOnly ToleranceQty, TolerancePct from row
        where row.CountGroupId == _countGroup
           && row.ItemGroupId  == _itemGroup;
    if (!row.RecId)
    {
        select firstOnly ToleranceQty, TolerancePct from row
            where row.CountGroupId == _countGroup
               && row.ItemGroupId  == '';
    }
    if (!row.RecId)
    {
        select firstOnly ToleranceQty, TolerancePct from row
            where row.CountGroupId == ''
               && row.ItemGroupId  == _itemGroup;
    }
    if (!row.RecId)
    {
        select firstOnly ToleranceQty, TolerancePct from row
            where row.CountGroupId == ''
               && row.ItemGroupId  == '';
    }
    return [row.ToleranceQty, row.TolerancePct];
}

public boolean validateWrite()
{
    boolean ret = super();

    if (this.TolerancePct < 0 || this.ToleranceQty < 0)
    {
        ret = checkFailed("Tolerance can't be negative.");
    }
    if (this.TolerancePct > 100)
    {
        ret = checkFailed("Tolerance % can't be more than 100.");
    }
    return ret;
}
